secondary_warning_release.text:
function _tickEnemyShotWarnings(sp){
  const list=G._shotWarnings;if(!list)return;
  let n=0;
  for(const w of list){
    const e=w.owner;
    const cancelled=(e._ch1StartMedium&&!_fieldEnemyCanShoot(e))||w.world!==ens||(!w.dead&&(!e.alive||e.stunned>0||e._frozen>0));
    if(!cancelled){
      w.t-=sp;
      if(w.t>0){list[n++]=w;continue;}
      const dx=w.dead?0:e.x-w.x,dy=w.dead?0:e.y-w.y;
      for(const shot of w.shots){shot.x=(shot.x??w.x)+dx;shot.y=(shot.y??w.y)+dy;shot._commit=true;spawnProj(shot);}
    }
    if(e._shotWarning===w)e._shotWarning=null;
  }
  list.length=n;

