child_elite_modifier_generation.text:
function rollMods(tier,si){
  const hell=SI_TO_HELL[si],cnt=ELITE_TIERS[tier].mods;
  const pool=MOD_DEFS.filter(m=>m.hell<=hell);if(!pool.length||!cnt)return[];
  const attacks=pool.filter(m=>m.id>='M29'&&m.id<='M32');
  const picked=[];
  const attackCount=Math.min(attacks.length,tier>=3?2:1);
  while(picked.length<attackCount){const i=~~(Math.random()*attacks.length);picked.push(attacks[i].id);attacks.splice(i,1)}
  const avail=pool.filter(m=>m.id<'M29'&&!picked.includes(m.id));
  while(picked.length<cnt&&avail.length){const i=~~(Math.random()*avail.length);picked.push(avail[i].id);avail.splice(i,1)}
  return picked;
